-- Đồng bộ identity PostgreSQL sau khi chèn ID mẫu.
SELECT setval(pg_get_serial_sequence('"branches"', 'Id'), COALESCE((SELECT MAX("Id") FROM "branches"), 1), EXISTS (SELECT 1 FROM "branches"));
